import { Injectable, Controller, Post, Body, Get, Param } from '@nestjs/common';
import { Pool } from 'pg';

// Wallet transfer service - handles balance transfers between accounts
@Injectable()
export class WalletService {
  private pool: Pool;

  constructor() {
    this.pool = new Pool({
      host: process.env.DB_HOST || 'localhost',
      port: parseInt(process.env.DB_PORT || '5432'),
      database: 'wallets',
      user: process.env.DB_USER || 'app',
      password: process.env.DB_PASSWORD || 'secret',
      max: 20,
      idleTimeoutMillis: 30000,
    });
  }

  async getBalance(accountId: string): Promise<number> {
    const result = await this.pool.query(
      'SELECT balance FROM accounts WHERE id = $1',
      [accountId]
    );
    return result.rows[0]?.balance || 0;
  }

  async transfer(fromId: string, toId: string, amount: number): Promise<{ success: boolean; message: string }> {
    // Step 1: Check sender balance
    const balanceResult = await this.pool.query(
      'SELECT balance FROM accounts WHERE id = $1',
      [fromId]
    );

    const currentBalance = balanceResult.rows[0]?.balance;
    if (!currentBalance || currentBalance < amount) {
      return { success: false, message: 'Insufficient funds' };
    }

    // Step 2: Deduct from sender
    await this.pool.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId]
    );

    // Step 3: Credit receiver
    await this.pool.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId]
    );

    // Step 4: Log the transfer
    await this.pool.query(
      'INSERT INTO transfer_log (from_account, to_account, amount, timestamp) VALUES ($1, $2, $3, NOW())',
      [fromId, toId, amount]
    );

    return { success: true, message: `Transferred ${amount} from ${fromId} to ${toId}` };
  }

  async batchTransfer(transfers: Array<{ from: string; to: string; amount: number }>): Promise<any[]> {
    // Process transfers concurrently for performance
    const results = await Promise.all(
      transfers.map(t => this.transfer(t.from, t.to, t.amount))
    );
    return results;
  }
}

@Controller('wallet')
export class WalletController {
  constructor(private readonly walletService: WalletService) {}

  @Get('balance/:accountId')
  async getBalance(@Param('accountId') accountId: string) {
    const balance = await this.walletService.getBalance(accountId);
    return { accountId, balance };
  }

  @Post('transfer')
  async transfer(@Body() body: { from: string; to: string; amount: number }) {
    if (!body.from || !body.to || !body.amount || body.amount <= 0) {
      return { success: false, message: 'Invalid transfer parameters' };
    }
    return this.walletService.transfer(body.from, body.to, body.amount);
  }

  @Post('batch-transfer')
  async batchTransfer(@Body() body: { transfers: Array<{ from: string; to: string; amount: number }> }) {
    if (!body.transfers || !Array.isArray(body.transfers)) {
      return { success: false, message: 'Invalid batch format' };
    }
    return this.walletService.batchTransfer(body.transfers);
  }
}

